import { Redirect, Route, Switch } from "wouter-preact";
import { Board } from "./board";
import { Landing } from "./landing";

export const decodeBoardId = (segment: string): string => {
  try {
    return decodeURIComponent(segment);
  } catch {
    return segment;
  }
};

export function App() {
  return (
    <Switch>
      <Route path="/b/:boardId">
        {(params) => {
          const boardId = decodeBoardId(params.boardId);
          return <Board key={boardId} boardId={boardId} />;
        }}
      </Route>
      <Route path="/">
        <Landing />
      </Route>
      <Route>
        <Redirect to="/" replace />
      </Route>
    </Switch>
  );
}
export const ID_ALPHABET = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-_";

export const ID_LENGTH = 12;

export const randomBoardId = (): string => {
  const bytes = crypto.getRandomValues(new Uint8Array(ID_LENGTH));
  let id = "";
  for (const byte of bytes) id += ID_ALPHABET[byte % ID_ALPHABET.length];
  return id;
};
import { isBoardId } from "@stallion/client-sync";
import { describe, expect, it } from "vitest";
import { ID_ALPHABET, ID_LENGTH, randomBoardId } from "./id";

describe("randomBoardId", () => {
  it("uses an alphabet of exactly 64 characters so a random byte is unbiased", () => {
    expect(ID_ALPHABET).toHaveLength(64);
    expect(new Set(ID_ALPHABET).size).toBe(64);
  });

  it("generates 12 characters the server's board id pattern accepts", () => {
    const id = randomBoardId();
    expect(id).toHaveLength(ID_LENGTH);
    expect(isBoardId(id)).toBe(true);
    for (const char of id) expect(ID_ALPHABET).toContain(char);
  });

  it("does not repeat across a large sample", () => {
    const ids = new Set(Array.from({ length: 500 }, () => randomBoardId()));
    expect(ids.size).toBe(500);
  });
});
export const DEFAULT_BOARD = "default";

export type RecentBoard = {
  id: string;
  name: string;
  lastOpened: number;
  thumbnail: string;
  renamedAt: number;
};

export const RECENTS_KEY = "stallion:recents";

export const MAX_RECENTS = 200;

type RecentsStorage = Pick<Storage, "getItem" | "setItem">;

type StoredRecent = Omit<RecentBoard, "renamedAt"> & { renamedAt?: number };

const isStoredRecent = (value: unknown): value is StoredRecent => {
  if (typeof value !== "object" || value === null) return false;
  const { id, name, lastOpened, thumbnail, renamedAt } = value as Record<string, unknown>;
  return (
    typeof id === "string" &&
    typeof name === "string" &&
    typeof lastOpened === "number" &&
    typeof thumbnail === "string" &&
    (renamedAt === undefined || typeof renamedAt === "number")
  );
};

const fromStored = (stored: StoredRecent): RecentBoard => ({
  ...stored,
  renamedAt: stored.renamedAt ?? 0,
});

const seedDefault = (): RecentBoard[] => [
  { id: DEFAULT_BOARD, name: DEFAULT_BOARD, lastOpened: 0, thumbnail: "", renamedAt: 0 },
];

export const loadRecents = (storage: RecentsStorage): RecentBoard[] => {
  const raw = storage.getItem(RECENTS_KEY);
  if (raw === null) return seedDefault();
  try {
    const parsed: unknown = JSON.parse(raw);
    return Array.isArray(parsed) ? parsed.filter(isStoredRecent).map(fromStored) : [];
  } catch {
    return [];
  }
};

export const saveRecents = (storage: RecentsStorage, recents: readonly RecentBoard[]): void => {
  try {
    storage.setItem(RECENTS_KEY, JSON.stringify(recents));
  } catch {
    // Recents are a per-device convenience; losing a write only forgets recency.
  }
};

export const sortByRecency = (recents: readonly RecentBoard[]): RecentBoard[] =>
  [...recents].sort((a, b) => b.lastOpened - a.lastOpened).slice(0, MAX_RECENTS);

export type RecentPatch = { id: string } & Partial<Omit<RecentBoard, "id">>;

export const upsertRecent = (
  recents: readonly RecentBoard[],
  patch: RecentPatch,
): RecentBoard[] => {
  const existing = recents.find((recent) => recent.id === patch.id);
  const merged: RecentBoard = {
    id: patch.id,
    name: patch.name ?? existing?.name ?? patch.id,
    lastOpened: patch.lastOpened ?? Date.now(),
    thumbnail: patch.thumbnail ?? existing?.thumbnail ?? "",
    renamedAt: patch.renamedAt ?? existing?.renamedAt ?? 0,
  };
  const rest = recents.filter((recent) => recent.id !== patch.id);
  return sortByRecency([merged, ...rest]);
};

export const removeRecent = (recents: readonly RecentBoard[], id: string): RecentBoard[] =>
  recents.filter((recent) => recent.id !== id);

export const renameRecent = (
  recents: readonly RecentBoard[],
  id: string,
  name: string,
  renamedAt: number = Date.now(),
): RecentBoard[] =>
  recents.map((recent) => (recent.id === id ? { ...recent, name, renamedAt } : recent));
import { useEffect, useRef, useState } from "preact/hooks";
import QRCode from "qrcode";
import { errorMessage } from "./report";
import type { BoardSource } from "./sync";

export const PIN_PATTERN = /^\d{6}$/;

export const boardLink = (origin: string, boardId: string): string =>
  `${origin}/b/${encodeURIComponent(boardId)}`;

type PinSource = Pick<BoardSource, "pinState" | "setPin">;

type ShareProps = {
  link: string;
  source: PinSource | undefined;
  onClose: () => void;
};

type PinView =
  | { state: "Checking" }
  | { state: "Known"; pinSet: boolean }
  | { state: "Failed"; message: string };

export const copyText = async (text: string, input: HTMLInputElement | null): Promise<string> => {
  const clipboard = globalThis.navigator?.clipboard;
  if (clipboard?.writeText) {
    const copied = await clipboard.writeText(text).then(
      () => true,
      () => false,
    );
    if (copied) return "Link copied.";
  }
  input?.focus();
  input?.select();
  if (document.execCommand?.("copy")) return "Link copied.";
  return "Link selected: copy it from the field.";
};

export function SharePanel({ link, source, onClose }: ShareProps) {
  const [qr, setQr] = useState<string | undefined>(undefined);
  const [qrError, setQrError] = useState<string | undefined>(undefined);
  const [pin, setPin] = useState<PinView>({ state: "Checking" });
  const [draft, setDraft] = useState("");
  const [busy, setBusy] = useState(false);
  const [result, setResult] = useState<{ ok: boolean; message: string } | undefined>(undefined);
  const [copied, setCopied] = useState<string | undefined>(undefined);
  const linkRef = useRef<HTMLInputElement>(null);
  const rootRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    let live = true;
    QRCode.toString(link, { type: "svg", margin: 1, errorCorrectionLevel: "M" }).then(
      (svg) => live && setQr(svg),
      (error: unknown) => live && setQrError(`Could not draw the QR code: ${errorMessage(error)}`),
    );
    return () => {
      live = false;
    };
  }, [link]);

  useEffect(() => {
    if (!source) {
      setPin({ state: "Failed", message: "the board is not open" });
      return;
    }
    let live = true;
    source.pinState().then((state) => {
      if (!live) return;
      setPin(
        state.ok
          ? { state: "Known", pinSet: state.pinSet }
          : { state: "Failed", message: state.message },
      );
    });
    return () => {
      live = false;
    };
  }, [source]);

  useEffect(() => {
    const close = (event: PointerEvent) => {
      if (event.target instanceof Node && rootRef.current?.contains(event.target)) return;
      if (event.target instanceof Element && event.target.closest("[data-share-toggle]")) return;
      onClose();
    };
    const onEscape = (event: KeyboardEvent) => {
      if (event.key === "Escape") onClose();
    };
    window.addEventListener("pointerdown", close);
    window.addEventListener("keydown", onEscape);
    return () => {
      window.removeEventListener("pointerdown", close);
      window.removeEventListener("keydown", onEscape);
    };
  }, [onClose]);

  const apply = async (next: string) => {
    if (!source) return;
    setBusy(true);
    setResult(undefined);
    const outcome = await source.setPin(next);
    setBusy(false);
    if (!outcome.ok) {
      setResult({ ok: false, message: `Could not update the PIN: ${outcome.message}` });
      return;
    }
    setPin({ state: "Known", pinSet: outcome.pinSet });
    setDraft("");
    setResult({
      ok: true,
      message: outcome.pinSet ? "PIN set." : "PIN removed: anyone with the link can join.",
    });
  };

  const pinSet = pin.state === "Known" && pin.pinSet;

  return (
    <div class="share" role="dialog" aria-label="Share this board" ref={rootRef}>
      <h2>Share this board</h2>
      <div class="share-link">
        <input
          ref={linkRef}
          class="field"
          type="text"
          readOnly
          value={link}
          aria-label="Board link"
          onFocus={(event) => event.currentTarget.select()}
        />
        <button
          type="button"
          class="action"
          onClick={() => copyText(link, linkRef.current).then(setCopied)}
        >
          Copy link
        </button>
      </div>
      {copied && (
        <p class="share-note" role="status">
          {copied}
        </p>
      )}
      <div class="share-qr" aria-label="QR code of the board link" role="img">
        {qr ? (
          <div class="qr" dangerouslySetInnerHTML={{ __html: qr }} />
        ) : (
          <p class="share-note">{qrError ?? "Drawing the QR code…"}</p>
        )}
      </div>
      <p class="share-pin" data-pin-state={pin.state === "Known" ? String(pin.pinSet) : pin.state}>
        {pin.state === "Checking" && "Checking the PIN…"}
        {pin.state === "Failed" && `Could not read the PIN state: ${pin.message}`}
        {pin.state === "Known" &&
          (pin.pinSet
            ? "PIN set: people with the link need the PIN to join."
            : "No PIN: anyone with the link can join.")}
      </p>
      <form
        class="share-form"
        onSubmit={(event) => {
          event.preventDefault();
          if (PIN_PATTERN.test(draft)) apply(draft);
        }}
      >
        <input
          class="field pin"
          type="text"
          inputMode="numeric"
          autoComplete="off"
          pattern="\d{6}"
          maxLength={6}
          placeholder="6 digits"
          aria-label={pinSet ? "New PIN" : "PIN"}
          value={draft}
          onInput={(event) => setDraft(event.currentTarget.value.replace(/\D/g, ""))}
        />
        <button type="submit" class="action" disabled={busy || !PIN_PATTERN.test(draft)}>
          {pinSet ? "Change PIN" : "Set PIN"}
        </button>
        {pinSet && (
          <button type="button" class="action quiet" disabled={busy} onClick={() => apply("")}>
            Remove PIN
          </button>
        )}
      </form>
      {result && (
        <p
          class={result.ok ? "share-note" : "share-note failed"}
          role={result.ok ? "status" : "alert"}
        >
          {result.message}
        </p>
      )}
    </div>
  );
}
