  it("declares an installable standalone app that opens the landing page", () => {
    expect(manifest).toMatchObject({
      name: "Stallion",
      short_name: "Stallion",
      display: "standalone",
      orientation: "any",
      start_url: "/",
    });
  });

  it("paints the splash and title bar in the canvas paper colour", () => {
    expect(PAPER).toBe(CANVAS_PAPER);
