import { openBoard } from "@stallion/client-sync";
import { useCallback, useEffect, useRef, useState } from "preact/hooks";
import { myBoardsForPage, thumbnailUploader } from "./my-boards";
import { PinPrompt } from "./pin-prompt";
import type { Presence } from "./presence";
import { loadRecents, saveRecents, upsertRecent } from "./recents";
import { errorMessage, reportLink } from "./report";
import { boardLink, SharePanel } from "./share";
import { createSurface, type Surface, type SurfaceView, type Tool, type ToolMode } from "./surface";
import { type BoardSource, type Connection, openSource, syncUrlFor } from "./sync";
import { captureThumbnail } from "./thumbnail";
import { type HistoryState, Toolbar } from "./toolbar";

const EMPTY_HISTORY: HistoryState = { canUndo: false, canRedo: false };

const INITIAL_VIEW: SurfaceView = { level: 0, contentLevels: [] };

const THUMBNAIL_DELAY_MS = 2000;

const NO_PRESENCE: Presence = { peers: [], following: undefined };

const historyKey = (event: KeyboardEvent): "Undo" | "Redo" | undefined => {
  if (!(event.ctrlKey || event.metaKey) || event.altKey) return undefined;
  const key = event.key.toLowerCase();
  if (key === "z") return event.shiftKey ? "Redo" : "Undo";
  if (key === "y" && !event.shiftKey) return "Redo";
  return undefined;
};

const SURFACE_CLASS: Record<ToolMode, string> = {
  Pencil: "surface",
  Pan: "surface panning",
  Eraser: "surface erasing",
  Select: "surface selecting",
};

export function Board({ boardId }: { boardId: string }) {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [tool, setTool] = useState<Tool>({
    size: "Medium",
    primary: 0,
    secondary: 4,
    mode: "Pencil",
  });
  const [error, setError] = useState<string | undefined>(undefined);
  const [connection, setConnection] = useState<Connection>("LocalOnly");
  const [history, setHistory] = useState<HistoryState>(EMPTY_HISTORY);
  const [view, setView] = useState<SurfaceView>(INITIAL_VIEW);
  const [shareOpen, setShareOpen] = useState(false);
  const [presence, setPresence] = useState<Presence>(NO_PRESENCE);
  const sourceRef = useRef<BoardSource | undefined>(undefined);
  const surfaceRef = useRef<Surface | undefined>(undefined);
  const toolRef = useRef(tool);
  toolRef.current = tool;
  const closeShare = useCallback(() => setShareOpen(false), []);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const openedAt = Date.now();
    saveRecents(
      localStorage,
      upsertRecent(loadRecents(localStorage), { id: boardId, lastOpened: openedAt }),
    );
    const api = myBoardsForPage();
    void api?.upsert(boardId, { lastOpened: openedAt });
    const uploads = thumbnailUploader((thumbnail) => {
      void api?.upsert(boardId, { thumbnail });
    });
    const source = openSource({
      url: syncUrlFor(import.meta.env.VITE_SYNC_URL, window.location),
      boardId,
      openBoard,
      onConnection: setConnection,
      onError: setError,
    });
    sourceRef.current = source;
    const syncHistory = () =>
      setHistory({ canUndo: source.history.canUndo, canRedo: source.history.canRedo });
    const unobserve = source.history.observe(syncHistory);
    const onKey = (event: KeyboardEvent) => {
      if (event.target instanceof HTMLInputElement) return;
      const action = historyKey(event);
      if (!action) return;
      event.preventDefault();
      if (action === "Undo") source.history.undo();
      else source.history.redo();
    };
    window.addEventListener("keydown", onKey);
    let thumbnailTimer: ReturnType<typeof setTimeout> | undefined;
    const saveThumbnail = () => {
      thumbnailTimer = undefined;
      const thumbnail = captureThumbnail(canvas);
      if (!thumbnail) return;
      saveRecents(
        localStorage,
        upsertRecent(loadRecents(localStorage), { id: boardId, thumbnail }),
      );
      uploads.push(thumbnail);
    };
    const scheduleThumbnail = () => {
      clearTimeout(thumbnailTimer);
      thumbnailTimer = setTimeout(saveThumbnail, THUMBNAIL_DELAY_MS);
    };
    let surface: Surface | undefined;
    try {
      surface = createSurface(
        canvas,
        boardId,
        source,
        () => toolRef.current,
        setView,
        scheduleThumbnail,
        setPresence,
      );
      surfaceRef.current = surface;
    } catch (failure) {
      setError(`Could not start the drawing surface: ${errorMessage(failure)}`);
    }
    return () => {
      if (thumbnailTimer !== undefined) {
        clearTimeout(thumbnailTimer);
        saveThumbnail();
      }
      uploads.flush();
      window.removeEventListener("keydown", onKey);
      unobserve();
      sourceRef.current = undefined;
      setHistory(EMPTY_HISTORY);
      setPresence(NO_PRESENCE);
      surfaceRef.current = undefined;
      surface?.dispose();
      source
        .close()
        .catch((failure: unknown) =>
          setError(`Could not close the board: ${errorMessage(failure)}`),
        );
    };
  }, [boardId]);

  return (
    <main class="board">
      <canvas
        ref={canvasRef}
        class={SURFACE_CLASS[tool.mode]}
        aria-label={`Drawing board ${boardId}`}
      />
      <Toolbar
        tool={tool}
        onChange={setTool}
        connection={connection}
        history={history}
        onUndo={() => sourceRef.current?.history.undo()}
        onRedo={() => sourceRef.current?.history.redo()}
        view={view}
        onLevel={(level) => surfaceRef.current?.zoomToLevel(level)}
        shareOpen={shareOpen}
        onShare={() => setShareOpen(!shareOpen)}
        presence={presence}
        onFollow={(clientId) => surfaceRef.current?.follow(clientId)}
      />
      {shareOpen && (
        <SharePanel
          link={boardLink(window.location.origin, boardId)}
          source={sourceRef.current}
          onClose={closeShare}
        />
      )}
      {connection === "Locked" && (
        <PinPrompt
          lock={sourceRef.current?.lock}
          onJoin={(pin) =>
            sourceRef.current
              ? sourceRef.current.join(pin)
              : Promise.resolve({ ok: false, reason: "Closed", message: "the board is not open" })
          }
        />
      )}
      {error && (
        <div class="error" role="alert">
          <p>{error}. Strokes may not be saved; reload to try again.</p>
          <a href={reportLink(error)} target="_blank" rel="noreferrer">
            Report an issue
          </a>
        </div>
      )}
    </main>
  );
}
import type { MyBoards } from "@stallion/client-sync";
import { useEffect, useMemo, useRef, useState } from "preact/hooks";
import { useLocation } from "wouter-preact";
import { randomBoardId } from "./id";
import { myBoardsForPage, syncBoards } from "./my-boards";
import { loadRecents, type RecentBoard, removeRecent, renameRecent, saveRecents } from "./recents";
import { reportLink } from "./report";

type Remote =
  | { state: "LocalOnly" }
  | { state: "Syncing" }
  | { state: "Synced" }
  | { state: "Offline" }
  | { state: "SignedOut"; message: string }
  | { state: "Failed"; message: string };

const remoteAfter = (reason: string, message: string): Remote => {
  if (reason === "NetworkError" && globalThis.navigator?.onLine === false) {
    return { state: "Offline" };
  }
  if (reason === "Http401" || reason === "Http403") return { state: "SignedOut", message };
  return { state: "Failed", message: `Could not sync your boards: ${message}` };
};

function RemoteNotice({ remote }: { remote: Remote }) {
  if (remote.state === "Offline") {
    return (
      <p class="landing-status" role="status">
        Offline: showing the boards on this device. They sync when you are back online.
      </p>
    );
  }
  if (remote.state === "SignedOut") {
    return (
      <div class="landing-alert" role="alert">
        <p>Your sign-in has expired, so your boards from other devices are missing.</p>
        <button type="button" class="action" onClick={() => window.location.reload()}>
          Sign in again
        </button>
      </div>
    );
  }
  if (remote.state === "Failed") {
    return (
      <div class="landing-alert" role="alert">
        <p>{remote.message}. Showing the boards on this device.</p>
        <a href={reportLink(remote.message)} target="_blank" rel="noreferrer">
          Report an issue
        </a>
      </div>
    );
  }
  return null;
}

const MINUTE_MS = 60_000;

const RELATIVE_UNITS: readonly [Intl.RelativeTimeFormatUnit, number][] = [
  ["year", 365 * 24 * 60 * MINUTE_MS],
  ["month", 30 * 24 * 60 * MINUTE_MS],
  ["week", 7 * 24 * 60 * MINUTE_MS],
  ["day", 24 * 60 * MINUTE_MS],
  ["hour", 60 * MINUTE_MS],
  ["minute", MINUTE_MS],
];

const relativeTimeFormat = new Intl.RelativeTimeFormat("en", { numeric: "auto" });

const relativeTime = (from: number, now: number): string => {
  const diff = Math.max(0, now - from);
  if (diff < MINUTE_MS) return "just now";
  for (const [unit, unitMs] of RELATIVE_UNITS) {
    if (diff >= unitMs) return relativeTimeFormat.format(-Math.round(diff / unitMs), unit);
  }
  return relativeTimeFormat.format(-Math.round(diff / MINUTE_MS), "minute");
};

export const lastOpenedLabel = (lastOpened: number, now: number): string =>
  lastOpened ? relativeTime(lastOpened, now) : "not opened yet";

export function Landing() {
  const [, navigate] = useLocation();
  const [recents, setRecents] = useState<RecentBoard[]>(() => loadRecents(localStorage));
  const api = useMemo<MyBoards | undefined>(myBoardsForPage, []);
  const [remote, setRemote] = useState<Remote>(() =>
    api ? { state: "Syncing" } : { state: "LocalOnly" },
  );
  const recentsRef = useRef(recents);
  recentsRef.current = recents;

  useEffect(() => {
    if (!api) return;
    let live = true;
    syncBoards(api, loadRecents(localStorage)).then((synced) => {
      if (!live) return;
      saveRecents(localStorage, synced.boards);
      setRecents(synced.boards);
      setRemote(
        synced.state === "Synced"
          ? { state: "Synced" }
          : remoteAfter(synced.reason, synced.message),
      );
    });
    return () => {
      live = false;
    };
  }, [api]);

  const createBoard = () => navigate(`/b/${randomBoardId()}`);

  const editName = (id: string, name: string) => {
    setRecents((current) => renameRecent(current, id, name));
  };

  const commitName = (id: string) => {
