    if (r.status() >= 400 && !r.url().endsWith("/favicon.ico")) errors.push(`HTTP ${r.status()} ${r.url()}`);
  });
  return { ctx, page };
};
const shot = (page, name) => page.screenshot({ path: join(DIR, `${name}.png`) });
const waitBoard = (page) => page.locator("canvas.surface").waitFor({ state: "visible", timeout: 15000 });

try {
  const a = await context();
  await a.page.goto(`${ORIGIN}/`, { waitUntil: "load" });
  await a.page.locator("main.landing").waitFor();
  await a.page.waitForFunction(() => document.querySelector("main.landing")?.dataset.sync !== "Syncing", null, { timeout: 15000 });
  const names = await a.page.locator(".recent-name").evaluateAll((els) => els.map((e) => e.value));
  const ids = await a.page.locator(".recent-name").evaluateAll((els) => els.map((e) => e.getAttribute("aria-label")));
  await shot(a.page, "1-landing");
  report("landing has no default board", !ids.some((l) => l === "Name for board default"), `rows=${names.length} sync=${await a.page.locator("main.landing").getAttribute("data-sync")}`);

  await a.page.getByRole("button", { name: "New board" }).click();
  await waitBoard(a.page);
  const newPath = new URL(a.page.url()).pathname;
  const id = newPath.split("/")[2];
  report("new board path", /^\/b\/[a-z0-9]{25}$/.test(newPath), newPath);
  await a.page.waitForTimeout(1500);
  await shot(a.page, "2-new-board");

  await a.page.evaluate(() => { window.__noReload = true; });
  await a.page.locator("[data-share-toggle]").click();
  const nameField = a.page.getByLabel("Board name");
  await nameField.fill("My Custom Board");
  await nameField.press("Enter");
  await a.page.waitForFunction((p) => location.pathname === p, `/b/${id}/my-custom-board`, { timeout: 5000 }).catch(() => {});
  const renamed = new URL(a.page.url()).pathname;
  const noReload = await a.page.evaluate(() => window.__noReload === true);
  report("rename rewrites url without reload", renamed === `/b/${id}/my-custom-board` && noReload, `${renamed} noReload=${noReload}`);
  await a.page.waitForTimeout(1500);
  const link = await a.page.getByLabel("Board link").inputValue();
  report("share link has id and slug", link === `${ORIGIN}/b/${id}/my-custom-board`, link);
  const qrSvg = await a.page.locator(".qr").innerHTML();
  const expected = await QRCode.toString(link, { type: "svg", margin: 1, errorCorrectionLevel: "M" });
  const qrPage = await a.ctx.newPage();
  const qrResp = await qrPage.goto(link, { waitUntil: "load" });
  await waitBoard(qrPage);
  report("qr encodes the link and the link opens", qrSvg === expected && qrResp?.ok() === true, `status=${qrResp?.status()} final=${new URL(qrPage.url()).pathname}`);
  await qrPage.close();
  await shot(a.page, "3-renamed-share");
  await a.page.waitForTimeout(1000);
  await a.ctx.close();

  const b = await context();
  await b.page.goto(`${ORIGIN}/b/${id}/stale-name`, { waitUntil: "load" });
  await waitBoard(b.page);
  await b.page.waitForFunction((p) => location.pathname === p, `/b/${id}/my-custom-board`, { timeout: 10000 }).catch(() => {});
  const fixed = new URL(b.page.url()).pathname;
  report("stale slug rewrites to current", fixed === `/b/${id}/my-custom-board`, fixed);
  await shot(b.page, "4-stale-fixed");

  await b.page.goto(`${ORIGIN}/b/default`, { waitUntil: "load" });
  await waitBoard(b.page);
  await b.page.waitForTimeout(2000);
  const oldPath = new URL(b.page.url()).pathname;
  const alert = await b.page.locator("[role=alert]").count();
  report("old-style id opens", oldPath.startsWith("/b/default") && alert === 0, `${oldPath} alerts=${alert}`);
  await shot(b.page, "5-old-id");
  await b.ctx.close();
} finally {
  await browser.close();
}
console.log(results.join("\n"));
console.log(`console/HTTP errors: ${errors.length}`);
for (const e of errors) console.log(`  ${e}`);
EOF
